using System.Collections.Concurrent;

public sealed class PriceCache(IPriceStore store)
{
    private readonly ConcurrentDictionary<string, decimal> _prices = new();

    public ValueTask<decimal> GetAsync(string sku) =>
        _prices.TryGetValue(sku, out var price)
            ? ValueTask.FromResult(price)              // hit: nothing allocated
            : new ValueTask<decimal>(LoadAsync(sku));  // miss: wraps a Task

    private async Task<decimal> LoadAsync(string sku)
    {
        var price = await store.LoadPriceAsync(sku);
        _prices[sku] = price;
        return price;
    }
}
